import{z as A,x as B,o as E,c as d,q as l,j as s,D as e,d as t,s as i,S as n,b as o}from"./chunks/framework.C8m1ZpeB.js";const f=JSON.parse('{"title":"远程证明","description":"","frontmatter":{"title":"远程证明","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/remote-attestation.md","filePath":"cs/remote-attestation.md","lastUpdated":1791063341000}'),p={name:"cs/remote-attestation.md"};function m(c,a,h,u,D,C){const r=B("Mermaid");return E(),d("div",null,[a[2]||(a[2]=l('<h1 id="远程证明" tabindex="-1">远程证明 <a class="header-anchor" href="#远程证明" aria-label="Permalink to &quot;远程证明&quot;">​</a></h1><div class="epigraph"><p>远程证明让验证者得到一份由硬件根签名的度量：启动了什么、飞地测量是什么。信任锚在厂商证书链，策略在验证者：度量不匹配就不交秘密。</p><footer>—— 据 Coker et al. 对证明架构；Intel SGX 远程证明文档；TPM PC Client 规范点名</footer></div><p>上一课<a href="/cs/confidential-computing">机密计算</a>说飞地要先证明自己、再拿密钥。本课补这条<strong>报价协议</strong>：谁签、签什么、如何吊销。不写伪造证明的步骤。</p><p>后课默认已经读完本课钉下的合同，只补差，不从该领域第一性原理重开。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>本地 TEE 的度量只有本机自己信，远端无法核实。远程证明补上这一步：验证者发随机挑战（防重放），TEE 返回引用（quote）——硬件私钥签名的度量与挑战；验证者沿厂商证书链验签，再与预期度量比对。缺口有两处：验证者的策略——哪些度量放行、密钥给谁——要自己定义；厂商基础设施（证书链、证明服务）的可用性成了新的依赖。</p><h3 id="吊销" tabindex="-1">吊销 <a class="header-anchor" href="#吊销" aria-label="Permalink to &quot;吊销&quot;">​</a></h3><p>CPU 微码漏洞曝光后，对应批次的证明密钥可能被厂商吊销。吊销抬高了安全下限，但已部署设备随之集体失能——可用性与安全再次打架，验证者策略里要预留灰度与豁免流程。</p><p><span class="marginnote">TPM/SGX 证明文献。quote 里的随机挑战防重放：换场景的旧报价不再有效。禁止伪造。安全启动下一课是本地链。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>协议四步：验证者发挑战，TEE 算度量，硬件签名打包成 quote，验证者验签并比对预期哈希，匹配才释放密钥。每一步都可能失败，验证者要显式写好「比对不上就拒绝」的路径，不能超时默认放行。下一课安全启动链：本地从 ROM 到内核。</p><p><span class="marginnote">术语翻译：quote（引用）就是「由芯片亲笔盖章的状态自述书」——里面装着本机启动了什么（度量值）、回答谁的提问（挑战）、盖章的私钥永不出芯片。远端核对的不是软件说了什么，而是「这枚章只有这块硅盖得出来」。</span></p><p><span class="marginnote">常见误区：初学者容易以为验签通过就等于机器安全。实际上验签只证明「这块硬件、跑了这份代码」，而这份代码有没有漏洞，验证者策略管不着——quote 是身份证明，不是漏洞扫描报告。</span></p>',13)),(E(),s(n,null,{default:e(()=>[i(r,{id:"mermaid-37",class:"mermaid",graph:"flowchart%20TD%0A%20%20CH%5B%22%E9%AA%8C%E8%AF%81%E8%80%85%E6%8C%91%E6%88%98%22%5D%20--%3E%20Q%5B%22%E7%A1%AC%E4%BB%B6%E7%AD%BE%E5%90%8D%E7%9A%84%E5%BA%A6%E9%87%8F%22%5D%0A%20%20Q%20--%3E%20POL%5B%22%E4%B8%8E%E9%A2%84%E6%9C%9F%E6%B5%8B%E9%87%8F%E6%AF%94%E5%AF%B9%22%5D%0A%20%20POL%20--%3E%20REL%5B%22%E9%87%8A%E6%94%BE%E5%AF%86%E9%92%A5%E6%88%96%E6%8B%92%E7%BB%9D%22%5D%0A"})]),fallback:e(()=>[...a[0]||(a[0]=[t(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=o("h2",{id:"机制",tabindex:"-1"},[t("机制 "),o("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[4]||(a[4]=o("p",null,"机制上是把「我是谁」的依据从软件自述换成硬件根：软件可以谎报版本，而度量在硅内算出、私钥不出芯片，谎报就得伪造签名。安全启动是同一度量机制在启动路径上的本地版本——先度量再执行，信任沿链传递。",-1)),(E(),s(n,null,{default:e(()=>[i(r,{id:"mermaid-44",class:"mermaid",graph:"flowchart%20TD%0A%20%20EV%5B%22%E9%AA%8C%E8%AF%81%E8%80%85%E6%94%B6%E5%88%B0%20quote%22%5D%20--%3E%20V1%5B%22%E9%AA%8C%E8%AF%81%E5%8E%82%E5%95%86%E8%AF%81%E4%B9%A6%E9%93%BE%22%5D%0A%20%20V1%20--%3E%20V2%7B%22%E6%8C%91%E6%88%98%E5%80%BC%E4%B8%80%E8%87%B4%3F%22%7D%0A%20%20V2%20--%20%22%E5%90%A6%22%20--%3E%20RJ1%5B%22%E6%8B%92%E7%BB%9D%3A%20%E7%96%91%E4%BC%BC%E9%87%8D%E6%94%BE%22%5D%0A%20%20V2%20--%20%22%E6%98%AF%22%20--%3E%20V3%7B%22%E5%90%8A%E9%94%80%E5%88%97%E8%A1%A8%E5%8C%85%E5%90%AB%E6%AD%A4%E5%AF%86%E9%92%A5%3F%22%7D%0A%20%20V3%20--%20%22%E6%98%AF%22%20--%3E%20RJ2%5B%22%E6%8B%92%E7%BB%9D%3A%20%E6%89%B9%E6%AC%A1%E5%B7%B2%E5%90%8A%E9%94%80%22%5D%0A%20%20V3%20--%20%22%E5%90%A6%22%20--%3E%20V4%7B%22%E5%BA%A6%E9%87%8F%3D%E9%A2%84%E6%9C%9F%E5%93%88%E5%B8%8C%3F%22%7D%0A%20%20V4%20--%20%22%E5%90%A6%22%20--%3E%20RJ3%5B%22%E6%8B%92%E7%BB%9D%3A%20%E8%BD%AF%E4%BB%B6%E6%A0%88%E4%B8%8D%E7%AC%A6%22%5D%0A%20%20V4%20--%20%22%E6%98%AF%22%20--%3E%20OK%5B%22%E9%87%8A%E6%94%BE%E5%AF%86%E9%92%A5%22%5D%0A"})]),fallback:e(()=>[...a[1]||(a[1]=[t(" Loading... ",-1)])]),_:1})),a[5]||(a[5]=l('<p>这张图回答的问题是「验证者拿到 quote 后按什么顺序拒绝」：三道闸门依次是签名链、挑战一致性、度量比对，任何一环失败都必须走显式拒绝路径——超时默认放行等于没有证明。</p><p><span class="marginnote">为什么重要：比对不上就放行，是最常见也是代价最高的实现错误——攻击者只要让验证服务超时，证明就形同虚设。策略代码里应把「拒绝」写成默认分支，「放行」只在全部条件显式满足时触发。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>不写伪造报价的方法，也不展开厂商证明服务的部署细节。安全启动链下一课。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>机密计算的密钥要等证明通过才释放。</li><li>报价 = 度量加挑战加硬件签名。</li><li>验证者策略与厂商证书链都在 TCB 里。</li><li>下一课安全启动链。</li><li>出处：Coker et al.；Intel SGX 证明；TPM 规范。</li></ul>',6))])}const T=A(p,[["render",m]]);export{f as __pageData,T as default};
